// ─────────────────────────────────────────────────────────────────────────
//  01 · fan-out with fallbacks★★★
//  concepts: CompletableFuture.allOf · exceptionally · ordering
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

class Exercise {

    /** One value per id in input order; failed fetches become the fallback; all started at once. */
    static CompletableFuture<List<String>> fetchAll(List<String> ids, Function<String, CompletableFuture<String>> fetch, String fallback) {
        List<CompletableFuture<String>> futures = ids.stream()
            .map(id -> fetch.apply(id).exceptionally(e -> fallback))
            .toList();
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
            .thenApply(v -> futures.stream().map(CompletableFuture::join).toList());
    }

    static CompletableFuture<String> delayed(String value, long ms) {
        return CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(ms); } catch (InterruptedException e) { throw new IllegalStateException(e); }
            return value;
        }, POOL);
    }

    static final ExecutorService POOL = Executors.newFixedThreadPool(8, r -> { var t = new Thread(r); t.setDaemon(true); return t; });

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("results keep input order", () -> eq(fetchAll(List.of("a", "b", "c"), id -> delayed(id.toUpperCase(), id.equals("a") ? 80 : 10), "?").join(), List.of("A", "B", "C")));
        test("a failing fetch becomes the fallback", () -> eq(fetchAll(List.of("ok", "bad"), id -> id.equals("bad") ? CompletableFuture.failedFuture(new IllegalStateException("down")) : delayed(id, 5), "n/a").join(), List.of("ok", "n/a")));
        test("the fetches run concurrently", () -> {
            long t0 = System.nanoTime();
            fetchAll(List.of("1", "2", "3", "4"), id -> delayed(id, 150), "?").join();
            long ms = (System.nanoTime() - t0) / 1_000_000;
            ok(ms < 450, "took " + ms + " ms; expected well under 600");
        });
        test("no ids completes with an empty list (boundary)", () -> eq(fetchAll(List.of(), id -> delayed(id, 1), "?").join(), List.of()));
        test("a fetch that throws synchronously is not recovered", () -> raises(IllegalArgumentException.class, () -> fetchAll(List.of("x"), id -> { throw new IllegalArgumentException("bad id"); }, "?")));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Recover each future on its own, then wait for all of them and join in order:

```java
List<CompletableFuture<String>> futures = ids.stream()
    .map(id -> fetch.apply(id).exceptionally(e -> fallback))
    .toList();
return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
    .thenApply(v -> futures.stream().map(CompletableFuture::join).toList());
```

`toList()` materialises the stream, so every fetch starts before `allOf` is built. Putting `exceptionally` on each future (not on the `allOf` result) is what turns one failure into one fallback instead of a failed page.
